#!/usr/bin/env python3
# -*- coding: utf-8 -*-
#
# Prepare GitTaskBench input/groundtruth files in the current workspace.
# Uses meta.json (generated by adapter_gittaskbench.py).

from __future__ import annotations

import json
import shutil
from pathlib import Path


def _copy_any(src: Path, dst: Path) -> None:
    if dst.exists():
        if dst.is_dir():
            shutil.rmtree(dst, ignore_errors=True)
        else:
            dst.unlink(missing_ok=True)
    dst.parent.mkdir(parents=True, exist_ok=True)
    if src.is_dir():
        shutil.copytree(src, dst, symlinks=True)
    else:
        shutil.copy2(src, dst)


def main() -> int:
    root = Path(__file__).resolve().parent
    meta_path = root / "meta.json"
    if not meta_path.exists():
        print("meta.json missing")
        return 2
    meta = json.loads(meta_path.read_text(encoding="utf-8"))
    inputs = meta.get("input_files") if isinstance(meta.get("input_files"), list) else []
    for item in inputs:
        src = Path(str(item.get("src_path") or "")).expanduser().resolve()
        dst = root / str(item.get("dst_path") or "")
        if not src.exists():
            print(f"input src missing: {src}")
            return 2
        _copy_any(src, dst)

    gt = meta.get("groundtruth")
    if isinstance(gt, dict):
        src = Path(str(gt.get("src_path") or "")).expanduser().resolve()
        dst = root / str(gt.get("dst_path") or "")
        if src.exists():
            _copy_any(src, dst)
    print("data prepared")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
